import { atom, read, update } from 'claude-code'
import type { HookStream, McpToolResult, ProcessSpawnChunk, ProcessSpawnResult, Register, Timer } from 'claude-code'

import type { ViewerMode, ViewerView } from '../types'
import { parseBmp, parseGlb } from './glb'
import type { ByteReader, ImageDecoder } from './glb'
import { cellFrame, infoLine, isTextured, makeModel, svgFrame, viewerPage } from './model'
import type { Model } from './model'
import { fromBase64 } from './render'

const PANE = 'meshy-viewer'
/** Degrees per rotate press, per dragged column and per auto-rotate tick (vector): 36 frames a turn. */
const STEP = 10
const SPIN_MS = 300
/** Live mode turns in finer steps, since every frame is a real render. */
const LIVE_STEP = 4
const LIVE_SPIN_MS = 120
const DRAG_DEGREES_PER_COLUMN = 3
const DRAG_DEGREES_PER_ROW = 6
const ZOOM_FACTOR = 0.85
/** Per wheel tick over the picture; a touchpad sends many. */
const WHEEL_ZOOM = 0.92
/** `$.fs.read` takes files up to 4 MiB; past that, ranges come through the shell. */
const SMALL_FILE = 4 * 1024 * 1024
const CHUNK = 3 * 1024 * 1024
const TOAST_MS = 6000
/** Base-color textures are sampled from a copy this many pixels square. */
const TEXTURE_SIZE = 256
// Cuts the image out of the GLB and converts it to BMP: sips on macOS, else ImageMagick.
const DECODE_SCRIPT =
  'd=$(mktemp -d) || exit 1; trap \'rm -rf "${d:?}"\' EXIT; ' +
  'tail -c +"$2" "$1" | head -c "$3" > "$d/in" && ' +
  'if command -v sips >/dev/null 2>&1; then sips -s format bmp -z "$4" "$4" "$d/in" --out "$d/out.bmp" >/dev/null 2>&1; ' +
  'elif command -v magick >/dev/null 2>&1; then magick "$d/in" -resize "$4x$4!" "BMP3:$d/out.bmp"; else exit 2; fi && ' +
  'base64 < "$d/out.bmp" | tr -d "\\n"'
/** Where the live renderer's Chrome may be, unless MESHY_VIEWER_CHROME names one. */
const CHROME_CANDIDATES = [
  '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  '/Applications/Chromium.app/Contents/MacOS/Chromium',
  '/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge',
  '/Applications/Brave Browser.app/Contents/MacOS/Brave Browser',
  '/usr/bin/google-chrome',
  '/usr/bin/chromium',
  '/usr/bin/chromium-browser',
  '/snap/bin/chromium',
]
const NODE_CANDIDATES = ['/opt/homebrew/bin/node', '/usr/local/bin/node', '/usr/bin/node']
/** Pixels rendered per terminal cell in live mode, and the frame's cap. */
const CELL_PIXELS = { x: 10, y: 20 }
const MAX_FRAME = { width: 1280, height: 960 }
/**
 * The session's browser pane, where the desktop shows the real viewer: the tool as the model names it,
 * and the MCP server and tool behind it, which the mod calls itself.
 */
const BROWSER_PANES: readonly BrowserPane[] = [{ name: 'mcp__Claude_Browser__navigate', server: 'Claude_Browser', tool: 'navigate' }]
const SERVER_START_MS = 20_000

const CLOSED: ViewerView = { path: null, angle: 0, phi: 75, zoom: 105, isAutoRotating: false, isOpen: false, mode: 'vector' }
const view = atom({ plugin: 'meshy-viewer', key: 'view' } as const, CLOSED)
const hint = atom({ plugin: 'meshy-viewer', key: 'hint' } as const, null)
const dismissed = atom({ plugin: 'meshy-viewer', key: 'dismissed' } as const, [])
// meshy-tray's tasks, when that mod is loaded: a finished one earns a "View" offer.
const trayTasks = { plugin: 'meshy-tray', key: 'tasks' } as const

const snap = (angle: number) => (((Math.round(angle / STEP) * STEP) % 360) + 360) % 360
const wrap = (angle: number) => ((Math.round(angle) % 360) + 360) % 360
/**
 * "Rotate right" (direction 1) moves the model's front to the right. The
 * vector renderer's angle grows that way; model-viewer's theta grows the
 * other way, so each mode turns its own way.
 */
const turnBy = (now: ViewerView, direction: number) =>
  now.mode === 'live' ? wrap(now.angle - direction * LIVE_STEP) : snap(now.angle + direction * STEP)
const tiltBy = (now: ViewerView, direction: number) => clampPhi(now.phi + direction * DRAG_DEGREES_PER_ROW)
const clampPhi = (phi: number) => Math.max(5, Math.min(175, Math.round(phi)))
const clampZoom = (zoom: number) => Math.max(25, Math.min(400, Math.round(zoom)))
const errorText = (error: unknown) => (error instanceof Error ? error.message : String(error))
/** An MCP result's text blocks as one line. */
const mcpText = (result: McpToolResult) => result.content.map(block => block.text ?? '').join(' ').trim()
const baseName = (path: string) => path.split('/').pop() ?? path
/** A view as stored by any version of this mod, every field filled in. */
const whole = (stored: Partial<ViewerView> | undefined): ViewerView => ({ ...CLOSED, ...stored })

/** The renderer process, while live mode runs. */
type Live = {
  socket: string
  outDir: string
  stream: HookStream<ProcessSpawnChunk, ProcessSpawnResult>
  ready: Promise<void>
  isGone: boolean
  /** The model the page shows, once /load answered. */
  loadedPath?: string
  /** The camera of the last frame asked for. */
  camera?: Camera
  generation: number
  width: number
  height: number
}

/** The local page server, while the desktop's browser pane shows a model. */
type Served = {
  path: string
  url: string
  stream: HookStream<ProcessSpawnChunk, ProcessSpawnResult>
}

type Camera = { theta: number; phi: number; radius: number }
type BrowserPane = { name: `mcp__${string}__${string}`; server: string; tool: string }

export const register: Register = on => {
  // Parsed models outlive a redraw but not a reload; $.state keeps which one is shown.
  const models = new Map<string, Model>()
  const loading = new Map<string, Promise<Model>>()
  let loadModel: ((path: string) => Promise<Model>) | undefined
  let openInBrowser: ((path: string) => Promise<string>) | undefined
  let startSpin: (() => void) | undefined
  let spin: Timer | undefined
  let live: Live | undefined
  let isGraphicsTerminal = false
  /** The rows the picture took at the last terminal draw: the wheel zooms over them. */
  let pictureRows = 0
  /** Shows the view's camera in live mode; resolves true once a new frame for it is on disk. */
  let showLive: ((path: string, size: { width: number; height: number }) => Promise<boolean>) | undefined
  let stopLive: (() => Promise<void>) | undefined
  /** Opens the model in the session's browser pane (desktop) through the pane's own MCP server; resolves the page's URL. */
  let openInPane: ((path: string) => Promise<string>) | undefined
  let served: Served | undefined
  let browserPane: BrowserPane | undefined

  on('session.start', async ($, e, next) => {
    const readerFor = async (path: string): Promise<{ size: number; read: ByteReader }> => {
      const { size } = await $.fs.stat(path)
      if (size <= SMALL_FILE) {
        const { base64 } = await $.fs.read(path, { as: 'bytes' })
        const bytes = fromBase64(base64)

        return { size, read: async (offset, length) => bytes.subarray(offset, offset + length) }
      }

      return {
        size,
        read: async (offset, length) => {
          const out = new Uint8Array(length)
          for (let at = 0; at < length; at += CHUNK) {
            const count = Math.min(CHUNK, length - at)
            // Positional arguments, so the path is never parsed by the shell.
            const ran = await $.process.run(
              ['sh', '-c', 'tail -c +"$2" "$1" | head -c "$3" | base64 | tr -d "\\n"', 'sh', path, String(offset + at + 1), String(count)],
              { timeoutMs: 120_000 },
            )
            if (ran.exitCode !== 0) throw new Error(`could not read ${baseName(path)}: ${ran.stderr.trim()}`)
            out.set(fromBase64(ran.stdout).subarray(0, count), at)
          }

          return out
        },
      }
    }

    const decoderFor =
      (path: string): ImageDecoder =>
      async ({ offset, length, mimeType }) => {
        if (!/^image\/(jpeg|png)$/.test(mimeType)) return undefined
        const ran = await $.process
          .run(['sh', '-c', DECODE_SCRIPT, 'sh', path, String(offset + 1), String(length), String(TEXTURE_SIZE)], {
            timeoutMs: 60_000,
          })
          .catch(() => undefined)

        // No converter, or one that failed: the model keeps its clay color.
        return ran?.exitCode === 0 && ran.stdout ? parseBmp(fromBase64(ran.stdout)) : undefined
      }

    loadModel = path => {
      const cached = models.get(path)
      if (cached) return Promise.resolve(cached)
      let pending = loading.get(path)
      if (!pending) {
        pending = (async () => {
          const { size, read: readBytes } = await readerFor(path)
          const model = makeModel(path, size, await parseGlb(readBytes, size, decoderFor(path)))
          // Decimate now, so drawing a frame is only the projection.
          svgFrame(model, 0)
          models.set(path, model)

          return model
        })().finally(() => loading.delete(path))
        loading.set(path, pending)
      }

      return pending
    }

    openInBrowser = async path => {
      const name = baseName(path)
      const folder = `${path.slice(0, path.length - name.length)}.meshy-viewer`
      const page = `${folder}/${name.replace(/\.glb$/i, '')}.html`
      const { head, tail } = viewerPage(name)
      await $.process.run(['mkdir', '-p', folder])
      // The GLB streams through base64 between the page's two halves: no size limit here.
      const wrote = await $.process.run(
        ['sh', '-c', '{ printf "%s" "$2"; base64 < "$1" | tr -d "\\n"; printf "%s" "$3"; } > "$4"', 'sh', path, head, tail, page],
        { timeoutMs: 120_000 },
      )
      if (wrote.exitCode !== 0) throw new Error(`could not write ${page}: ${wrote.stderr.trim()}`)
      const opened = await $.process.run(['open', page]).catch(() => undefined)
      if (opened?.exitCode !== 0) {
        const fallback = await $.process.run(['xdg-open', page]).catch(() => undefined)
        if (fallback?.exitCode !== 0) throw new Error(`wrote ${page} but could not open a browser`)
      }

      return page
    }

    // --- live mode: a headless Chrome draws the frames ----------------------

    const termProgram = (await $.env.get('TERM_PROGRAM')) ?? ''
    const term = (await $.env.get('TERM')) ?? ''
    isGraphicsTerminal =
      termProgram === 'ghostty' || /ghostty|kitty/i.test(term) || (await $.env.get('KITTY_WINDOW_ID')) !== undefined

    const findChrome = async () => {
      const named = await $.env.get('MESHY_VIEWER_CHROME')
      for (const candidate of named ? [named, ...CHROME_CANDIDATES] : CHROME_CANDIDATES) {
        if (await $.fs.exists(candidate)) return candidate
      }
      throw new Error('no Chrome found; install Google Chrome or set MESHY_VIEWER_CHROME to a Chromium binary')
    }
    const findNode = async () => {
      for (const candidate of NODE_CANDIDATES) if (await $.fs.exists(candidate)) return candidate

      return 'node'
    }

    const ask = async (renderer: Live, route: string, body: unknown): Promise<Record<string, unknown>> => {
      const response = await $.http.fetch(`http://meshy-viewer${route}`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(body),
        socketPath: renderer.socket,
      })
      let json: Record<string, unknown> = {}
      try {
        json = JSON.parse(response.text)
      } catch {
        // An empty or broken answer reads as a failure below.
      }
      if (!response.ok) throw new Error(typeof json.error === 'string' ? json.error : `the renderer answered HTTP ${response.status}`)

      return json
    }

    const startRenderer = async (width: number, height: number): Promise<Live> => {
      const chrome = await findChrome()
      const node = await findNode()
      const tag = `${Date.now().toString(36)}${Math.floor(Math.random() * 1e6).toString(36)}`
      const outDir = `/tmp/meshy-viewer-${tag}`
      const socket = `/tmp/meshy-viewer-${tag}.sock`
      const stream = $.process.spawn({
        argv: [
          node,
          `${$.plugin.root}/bin/render.mjs`,
          '--chrome', chrome,
          '--socket', socket,
          '--out', outDir,
          '--width', String(width),
          '--height', String(height),
        ],
      })
      let markReady!: () => void
      let markFailed!: (error: Error) => void
      const ready = new Promise<void>((resolve, reject) => {
        markReady = resolve
        markFailed = reject
      })
      ready.catch(() => undefined)
      const renderer: Live = { socket, outDir, stream, ready, isGone: false, generation: 0, width, height }
      // The loop is the child's life: it runs on in the background until the renderer exits.
      void (async () => {
        let stderr = ''
        try {
          for await (const chunk of stream) {
            if (chunk.stream === 'stdout' && chunk.text.includes('ready')) markReady()
            else if (chunk.stream === 'stderr') stderr = (stderr + chunk.text).slice(-2000)
          }
        } catch (error) {
          stderr = `${stderr}\n${errorText(error)}`
        } finally {
          renderer.isGone = true
          const reason = stderr.trim().split('\n').pop() ?? ''
          markFailed(new Error(`the live renderer exited${reason ? `: ${reason}` : ''}`))
          if (live === renderer) {
            live = undefined
            $.ui.invalidate('ui.render')
          }
        }
      })()
      // Never let a renderer that fails to start hang the viewer.
      $.clock.after(30_000, () => markFailed(new Error('the live renderer did not start within 30s')))

      return renderer
    }

    let inFlight: Promise<void> | undefined
    let wanted: Camera | undefined

    const take = (renderer: Live, answer: Record<string, unknown>) => {
      if (typeof answer.generation === 'number') renderer.generation = answer.generation
    }
    // Two draws before the first renderer is up must not start two Chromes.
    let starting: Promise<Live> | undefined

    showLive = async (path, { width, height }) => {
      if (!live || live.isGone) {
        starting ??= startRenderer(width, height).finally(() => {
          starting = undefined
        })
        live = await starting
      }
      const renderer = live
      await renderer.ready
      if (renderer.loadedPath !== path || renderer.width !== width || renderer.height !== height) {
        const answer = await ask(renderer, '/load', { path, width, height })
        renderer.loadedPath = path
        renderer.width = width
        renderer.height = height
        renderer.camera = undefined
        take(renderer, answer)
      }
      const shown = whole(await read($, view))
      // Closed, or replaced, while the load ran: nothing more to ask of it.
      if (live !== renderer || renderer.isGone) return false
      const camera: Camera = { theta: shown.angle, phi: shown.phi, radius: shown.zoom }
      const last = renderer.camera
      // The frame on disk already shows this camera: a redraw asks for nothing.
      if (last && last.theta === camera.theta && last.phi === camera.phi && last.radius === camera.radius) return false
      wanted = camera
      // One request at a time; the camera the latest change asked for wins.
      if (!inFlight) {
        inFlight = (async () => {
          try {
            while (wanted && live === renderer && !renderer.isGone) {
              const asked = wanted
              wanted = undefined
              renderer.camera = asked
              take(renderer, await ask(renderer, '/frame', asked))
            }
          } finally {
            inFlight = undefined
          }
        })()
      }
      await inFlight

      return true
    }

    stopLive = async () => {
      const renderer = live
      live = undefined
      if (!renderer || renderer.isGone) return
      await ask(renderer, '/quit', {}).catch(() => undefined)
      await renderer.stream.return({ code: 0, signal: null }).catch(() => undefined)
    }

    const stopServer = async () => {
      const running = served
      served = undefined
      await running?.stream.return({ code: 0, signal: null }).catch(() => undefined)
    }

    openInPane = async path => {
      if (!browserPane) throw new Error('this session has no browser pane')
      if (served?.path !== path) {
        await stopServer()
        const node = await findNode()
        const stream = $.process.spawn({
          argv: [node, `${$.plugin.root}/bin/serve.mjs`, '--model', path, '--cache', '/tmp/meshy-viewer-cache'],
        })
        let settle!: (url: string) => void
        let fail!: (error: Error) => void
        const url = new Promise<string>((resolve, reject) => {
          settle = resolve
          fail = reject
        })
        url.catch(() => undefined)
        void (async () => {
          let stderr = ''
          try {
            for await (const chunk of stream) {
              const match = chunk.stream === 'stdout' ? /http:\/\/127\.0\.0\.1:\d+\//.exec(chunk.text) : null
              if (match) settle(match[0])
              else if (chunk.stream === 'stderr') stderr = (stderr + chunk.text).slice(-2000)
            }
          } catch (error) {
            stderr = `${stderr}\n${errorText(error)}`
          } finally {
            const reason = stderr.trim().split('\n').pop() ?? ''
            fail(new Error(`the model server exited${reason ? `: ${reason}` : ''}`))
            if (served?.stream === stream) served = undefined
          }
        })()
        $.clock.after(SERVER_START_MS, () => fail(new Error('the model server did not start within 20s')))
        served = { path, url: await url, stream }
      }
      // The mod calls the pane's MCP server itself: a plugin's own call is its grant, so the pane
      // opens at once. (A $.tool.call goes through the model-tool permission path, whose auto-mode
      // classifier holds no verdict for a call no model turn produced.)
      let opened: McpToolResult
      try {
        opened = await $.mcp.call(browserPane.server, browserPane.tool, { url: served.url })
      } catch (error) {
        // The server could not be called by name: let a model turn open the page with the tool,
        // submitted once this hook has answered (a hook holding the turn may not submit).
        const text = `Open ${served.url} in the built-in browser pane with the ${browserPane.name} tool. It is meshy-viewer's page for ${baseName(path)}; reply with one short line.`
        $.clock.after(50, () => void $.prompt.submit({ text }))

        return served.url
      }
      if (opened.isError) throw new Error(mcpText(opened) || 'the browser pane refused the page')

      return served.url
    }

    const tick = async () => {
      const shown = whole(await read($, view))
      if (!shown.isOpen || !shown.isAutoRotating) {
        spin?.cancel()
        spin = undefined
        return
      }
      const isLive = shown.mode === 'live'
      await update($, view, current => ({
        ...whole(current),
        angle: isLive ? wrap(whole(current).angle + LIVE_STEP) : snap(whole(current).angle + STEP),
      }))
    }
    startSpin = () => {
      if (spin) return
      void (async () => {
        const shown = whole(await read($, view))
        if (spin) return
        spin = $.clock.every(shown.mode === 'live' ? LIVE_SPIN_MS : SPIN_MS, () => void tick())
      })()
    }

    await $.command.register({
      name: 'meshy-view',
      description: 'View and spin a GLB model in a pane (default: the newest in ./meshy-models; --live or --vector picks the renderer)',
      argumentHint: '[path] [--live|--vector]',
    })

    const tools = new Set((await $.tool.list()).map(tool => tool.name))
    browserPane = BROWSER_PANES.find(pane => tools.has(pane.name))

    // After a reload: parse the model on screen again and keep it turning.
    const shown = whole(await read($, view))
    if (shown.path) {
      void loadModel(shown.path)
        .then(() => $.ui.invalidate('ui.render'))
        .catch(() => undefined)
    }
    if (shown.isOpen && shown.isAutoRotating) startSpin()

    return next(e)
  })

  on('command.run', { command: 'meshy-view' }, async ($, e) => {
    if (!loadModel) return { text: 'meshy-viewer is still starting; try again in a moment.' }
    const cwd = await $.session.cwd()
    let mode: ViewerMode | undefined
    const rest: string[] = []
    for (const word of e.args.trim().split(/\s+/).filter(Boolean)) {
      if (word === '--live') mode = 'live'
      else if (word === '--vector') mode = 'vector'
      else rest.push(word)
    }
    let path = rest.join(' ').replace(/^(["'])(.*)\1$/, '$2')
    if (!path) {
      const folder = `${cwd}/meshy-models`
      const glbs = (await $.fs.exists(folder))
        ? (await $.fs.list(folder)).filter(entry => entry.kind === 'file' && /\.glb$/i.test(entry.name))
        : []
      const newest = glbs.sort((a, b) => b.mtimeMs - a.mtimeMs)[0]
      if (!newest) return { text: 'No .glb files in ./meshy-models. Usage: /meshy-view [path to a .glb] [--live|--vector]' }
      path = `${folder}/${newest.name}`
    } else if (path.startsWith('~/')) {
      path = `${await $.env.get('HOME')}${path.slice(1)}`
    } else if (!path.startsWith('/')) {
      path = `${cwd}/${path}`
    }
    if (!(await $.fs.exists(path))) return { text: `No such file: ${path}` }

    // The desktop pane cannot draw pixels, but the session's browser pane can run the real viewer.
    const surfaces = await $.session.surfaces()
    if (surfaces.includes('desktop') && openInPane && mode === undefined) {
      try {
        const url = await openInPane(path)

        return { text: `Viewing ${baseName(path)} in the browser pane (${url}). Drag to orbit, scroll to zoom.` }
      } catch (error) {
        $.ui.toast(`Browser pane failed: ${errorText(error)}; opening the pane view`, { timeoutMs: TOAST_MS })
      }
    }

    let model: Model
    try {
      model = await loadModel(path)
    } catch (error) {
      return { text: `Could not read ${baseName(path)}: ${errorText(error)}` }
    }
    const chosen = path
    const chosenMode: ViewerMode = mode ?? (isGraphicsTerminal ? 'live' : 'vector')
    await update($, view, () => ({ ...CLOSED, path: chosen, isOpen: true, mode: chosenMode }))
    const placed = await $.ui.open({ id: PANE, title: model.name, focus: true, closeOnEscape: true })
    await update($, hint, () => (placed.isPlaced ? null : { path: chosen, reason: placed.reason }))

    return {
      text: placed.isPlaced
        ? `Viewing ${model.name}${chosenMode === 'live' ? ' (live)' : ''}.`
        : `The viewer pane is waiting (${placed.reason}); the line above the prompt can open ${model.name} in your browser instead.`,
    }
  })

  on('ui.close', { id: PANE }, async ($, e, next) => {
    await stopLive?.()
    await update($, view, current => ({ ...whole(current), isOpen: false, isAutoRotating: false }))

    return next(e)
  })

  // The drag layer posts how far the pointer moved, a key's turn or tilt, or a zoom step.
  on('ui.message', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const data = (e.data ?? {}) as { dx?: unknown; dy?: unknown; turn?: unknown; tilt?: unknown; zoom?: unknown }
    const dx = Number(data.dx) || 0
    const dy = Number(data.dy) || 0
    const turn = Number(data.turn) || 0
    const tilt = Number(data.tilt) || 0
    const zoom = Number(data.zoom) || 0
    if (dx === 0 && dy === 0 && turn === 0 && tilt === 0 && zoom === 0) return {}
    await update($, view, current => {
      const now = { ...whole(current), isAutoRotating: false }
      if (turn !== 0) now.angle = turnBy(now, turn)
      if (now.mode !== 'live') {
        // The model follows the pointer: a drag left turns it left.
        return { ...now, angle: dx === 0 ? now.angle : snap(now.angle + dx * STEP) }
      }
      if (tilt !== 0) now.phi = tiltBy(now, tilt)

      return {
        ...now,
        // The model follows the pointer sideways; dragging down brings its top into view.
        angle: wrap(now.angle - dx * DRAG_DEGREES_PER_COLUMN),
        phi: clampPhi(now.phi - dy * DRAG_DEGREES_PER_ROW),
        zoom: zoom === 0 ? now.zoom : clampZoom(now.zoom * (zoom > 0 ? ZOOM_FACTOR : 1 / ZOOM_FACTOR)),
      }
    })

    return {}
  })

  // The wheel over the picture zooms the live view; elsewhere it scrolls the pane.
  on('ui.scroll', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    const shown = whole(await read($, view))
    if (e.origin.kind !== 'person' || !e.pointer || shown.mode !== 'live' || !shown.isOpen) return next(e)
    // The tree's row under the pointer: the window before this move, plus the cell.
    const row = e.offset - e.by + e.pointer.row
    if (row < 0 || row >= pictureRows || e.pointer.column < 0) return next(e)
    const factor = (e.by < 0 ? WHEEL_ZOOM : 1 / WHEEL_ZOOM) ** Math.min(4, Math.abs(e.by))
    await update($, view, current => ({ ...whole(current), zoom: clampZoom(whole(current).zoom * factor) }))

    return {}
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const shown = whole(await read($, view))
    if (!shown.path) {
      return <Text dimColor>Run /meshy-view [path] to open a model.</Text>
    }
    const path = shown.path
    const model = models.get(path)
    if (!model) {
      return <Text dimColor>{`Loading ${baseName(path)}...`}</Text>
    }
    const isLive = shown.mode === 'live' && e.surface === 'terminal'
    const move = (change: Partial<ViewerView>) =>
      update($, view, current => ({ ...whole(current), isAutoRotating: false, ...change }))
    const turn = (direction: number) =>
      update($, view, current => {
        const now = whole(current)

        return { ...now, isAutoRotating: false, angle: turnBy(now, direction) }
      })
    const toggleSpin = async () => {
      const now = await update($, view, current => ({ ...whole(current), isAutoRotating: !whole(current).isAutoRotating }))
      if (now.isAutoRotating) startSpin?.()
    }
    const setMode = async (mode: ViewerMode) => {
      if (mode === 'vector') await stopLive?.()
      await update($, view, current => ({ ...whole(current), mode, isAutoRotating: false }))
    }
    // A close from this plugin's own button skips its ui.close hook, so it tidies up here.
    const close = async () => {
      await stopLive?.()
      await update($, view, current => ({ ...whole(current), isOpen: false, isAutoRotating: false }))
      await $.ui.close({ id: PANE })
    }
    const browse = async () => {
      try {
        const page = await openInBrowser?.(path)
        $.ui.toast(`Opened in your browser: ${page}`, { timeoutMs: TOAST_MS })
      } catch (error) {
        $.ui.toast(`Open in browser failed: ${errorText(error)}`, { timeoutMs: TOAST_MS })
      }
    }

    const controls = (
      <Box flexDirection="row" gap={1}>
        <Button key="left" label="Rotate left" hotkey="h" onPress={() => turn(-1)} />
        <Button key="right" label="Rotate right" hotkey="l" onPress={() => turn(1)} />
        {isLive ? <Button key="up" label="Tilt up" hotkey="k" onPress={() => move({ phi: tiltBy(shown, -1) })} /> : null}
        {isLive ? <Button key="down" label="Tilt down" hotkey="j" onPress={() => move({ phi: tiltBy(shown, 1) })} /> : null}
        {isLive ? <Button key="in" label="Zoom in" hotkey="i" onPress={() => move({ zoom: clampZoom(shown.zoom * ZOOM_FACTOR) })} /> : null}
        {isLive ? <Button key="out" label="Zoom out" hotkey="u" onPress={() => move({ zoom: clampZoom(shown.zoom / ZOOM_FACTOR) })} /> : null}
        <Button key="auto" label={shown.isAutoRotating ? 'Stop' : 'Auto-rotate'} hotkey="a" onPress={toggleSpin} />
        <Button key="reset" label="Reset" hotkey="r" onPress={() => move({ angle: 0, phi: CLOSED.phi, zoom: CLOSED.zoom })} />
        {e.surface === 'terminal' ? (
          <Button key="mode" label={isLive ? 'Vector' : 'Live'} hotkey="v" onPress={() => setMode(isLive ? 'vector' : 'live')} />
        ) : null}
        {e.surface === 'desktop' && browserPane ? (
          <Button key="pane" label="Open in browser pane" hotkey="p" variant="primary" onPress={() => openInPane?.(path).catch(error => $.ui.toast(`Browser pane failed: ${errorText(error)}`, { timeoutMs: TOAST_MS }))} />
        ) : null}
        <Button key="browser" label="Open in browser" hotkey="o" onPress={browse} />
        <Button key="close" label="Close" hotkey="q" role="dismiss" onPress={close} />
      </Box>
    )
    const status = isLive
      ? `${shown.angle} deg, tilt ${shown.phi}, zoom ${shown.zoom}%${shown.isAutoRotating ? ', auto-rotating' : ''}`
      : `${shown.angle} deg${shown.isAutoRotating ? ', auto-rotating' : ''}`
    const footer = (shownFaces: number, note?: string) => (
      <Box flexDirection="column">
        <Text dimColor wrap="truncate-end">{infoLine(model, shownFaces)}</Text>
        {note ? <Text dimColor wrap="truncate-end">{note}</Text> : null}
      </Box>
    )
    const textureNote = isTextured(model)
      ? model.mesh.colors
        ? 'Texture colors are sampled once per face; Live or Open in browser shows the full texture.'
        : 'Textures are not drawn here; Live or Open in browser shows them.'
      : undefined

    if (e.surface === 'terminal') {
      const { Raster, Client, Image } = $.ui.resolve(e)
      const columns = Math.max(16, Math.min(255, e.props.bodyColumns))
      const room = Math.max(6, (e.viewport?.rows ?? 30) - 8)
      const rows = Math.max(6, Math.min(255, room, Math.round(columns * 0.375)))
      pictureRows = rows
      // A transparent Client the size of the picture, laid over it: drag the model itself.
      const dragLayer = (
        <Box position="absolute" top={0} left={0}>
          <Client key="drag" module="./drag.tsx" width={columns} height={rows} props={{}} />
        </Box>
      )
      const strip = (
        <Text dimColor>{`${isLive ? 'drag the model to spin, scroll or +/- to zoom' : 'drag the model to spin'}  ${status}`}</Text>
      )

      if (isLive) {
        const renderer = live
        const isCurrent = renderer !== undefined && !renderer.isGone && renderer.loadedPath === path
        // Ask for this camera's frame; the redraw that follows draws it. A closing pane asks for nothing.
        if (shown.isOpen) {
          void showLive?.(path, {
            width: Math.min(MAX_FRAME.width, columns * CELL_PIXELS.x),
            height: Math.min(MAX_FRAME.height, rows * CELL_PIXELS.y),
          })
            .then(isNew => isNew && $.ui.invalidate('ui.render'))
            .catch(error => {
              $.ui.toast(`Live view failed: ${errorText(error)}; showing the vector view`, { timeoutMs: TOAST_MS })
              void setMode('vector')
            })
        }

        return (
          <Box flexDirection="column">
            <Box flexDirection="column" height={rows}>
              {isCurrent && renderer.generation > 0 ? (
                <Image
                  key="live"
                  source={{ file: `${renderer.outDir}/frame.png`, format: 'png', generation: renderer.generation }}
                  columns={columns}
                  rows={rows}
                  alt={`${model.name}: the live view needs a kitty-graphics terminal such as Ghostty; press v for the vector view`}
                />
              ) : (
                <Text dimColor>{`Starting the live renderer for ${model.name}...`}</Text>
              )}
              {dragLayer}
            </Box>
            {strip}
            {controls}
            {footer(model.mesh.triangleCount, 'Live: rendered by headless Chrome with model-viewer.')}
          </Box>
        )
      }

      const frame = cellFrame(model, shown.angle, columns, rows)

      return (
        <Box flexDirection="column">
          <Box flexDirection="column" height={rows}>
            <Raster key="model" columns={columns} rows={rows} cells={frame.cells} />
            {dragLayer}
          </Box>
          {strip}
          {controls}
          {footer(frame.shown, textureNote)}
        </Box>
      )
    }

    const frame = svgFrame(model, shown.angle)
    const alt = `${model.name}, turned ${shown.angle} degrees`
    if (e.surface === 'desktop') {
      const { Svg, Client } = $.ui.resolve(e)

      return (
        <Box flexDirection="column">
          <Svg source={frame.svg} alt={alt} />
          <Client key="drag" module="./drag.tsx" props={{ label: `<< drag here to spin >>  ${status}` }} />
          {controls}
          {footer(frame.shown, textureNote)}
        </Box>
      )
    }
    const { Svg } = $.ui.resolve(e)

    return (
      <Box flexDirection="column">
        <Svg source={frame.svg} alt={alt} />
        <Text dimColor>{status}</Text>
        {controls}
        {footer(frame.shown, textureNote)}
      </Box>
    )
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const waiting = await read($, hint)
    const taken = await read($, dismissed)
    const finished = ((await read($, trayTasks)) ?? []).filter(
      task => task.status === 'SUCCEEDED' && task.file && !taken.includes(task.id),
    )
    const offer = finished[finished.length - 1]
    if (!waiting && !offer) return next(e)

    const { Box, Text, Button } = $.ui.resolve(e)
    const below = await next(e)

    const viewOffer = async () => {
      if (!offer?.file || !loadModel) return
      const path = `${offer.cwd}/${offer.file.replace(/^\.\//, '')}`
      await update($, dismissed, list => [...list, offer.id])
      if (e.surface === 'desktop' && openInPane) {
        try {
          await openInPane(path)
          return
        } catch (error) {
          $.ui.toast(`Browser pane failed: ${errorText(error)}; opening the pane view`, { timeoutMs: TOAST_MS })
        }
      }
      try {
        await loadModel(path)
      } catch (error) {
        $.ui.toast(`Could not read ${baseName(path)}: ${errorText(error)}`, { timeoutMs: TOAST_MS })
        return
      }
      const mode: ViewerMode = isGraphicsTerminal ? 'live' : 'vector'
      await update($, view, () => ({ ...CLOSED, path, isOpen: true, mode }))
      const placed = await $.ui.open({ id: PANE, title: baseName(path), focus: true, closeOnEscape: true })
      await update($, hint, () => (placed.isPlaced ? null : { path, reason: placed.reason }))
    }
    const browseWaiting = async () => {
      if (!waiting) return
      try {
        const page = await openInBrowser?.(waiting.path)
        $.ui.toast(`Opened in your browser: ${page}`, { timeoutMs: TOAST_MS })
        await update($, hint, () => null)
      } catch (error) {
        $.ui.toast(`Open in browser failed: ${errorText(error)}`, { timeoutMs: TOAST_MS })
      }
    }

    return (
      <Box flexDirection="column">
        {offer ? (
          <Box key="offer" flexDirection="row" gap={1}>
            <Text wrap="truncate-end">{`Meshy model ready: ${offer.file}`}</Text>
            <Button key="view" label="View" hotkey="1" variant="primary" onPress={viewOffer} />
            <Button
              key="skip"
              label="Dismiss"
              hotkey="2"
              onPress={() => update($, dismissed, list => [...list, offer.id])}
            />
          </Box>
        ) : null}
        {waiting ? (
          <Box key="hint" flexDirection="row" gap={1}>
            <Text wrap="truncate-end">{`Viewer pane is waiting (${waiting.reason}).`}</Text>
            <Button key="browse" label="Open in browser" hotkey="3" onPress={browseWaiting} />
            <Button key="unhint" label="Dismiss" hotkey="4" onPress={() => update($, hint, () => null)} />
          </Box>
        ) : null}
        {below}
      </Box>
    )
  })
}

