import type { Mesh } from './glb'
import { decimate, project, toCells, toSvg } from './render'
import type { Faces } from './render'

/** The SVG element's limit is 131072 characters. */
const SVG_LIMIT = 130_000
const SVG_BUDGET = 3200
const CELL_BUDGET = 20_000
export const SVG_WIDTH = 640
export const SVG_HEIGHT = 480

export type Model = {
  path: string
  name: string
  size: number
  mesh: Mesh
  /** Faces per budget, and drawn frames per angle and size. */
  faces: Map<number, Faces>
  frames: Map<string, string>
  /** The faces the SVG frames draw, once the first one found its budget. */
  svgBudget: number
}

export const makeModel = (path: string, size: number, mesh: Mesh): Model => ({
  path,
  name: path.split('/').pop() ?? path,
  size,
  mesh,
  faces: new Map(),
  frames: new Map(),
  svgBudget: SVG_BUDGET,
})

const facesFor = (model: Model, budget: number) => {
  let faces = model.faces.get(budget)
  if (!faces) {
    faces = decimate(model.mesh, budget)
    model.faces.set(budget, faces)
  }

  return faces
}

const remember = (model: Model, key: string, value: string) => {
  // 36 angles on two surfaces is all a session needs; a resize starts over.
  if (model.frames.size > 96) model.frames.clear()
  model.frames.set(key, value)

  return value
}

/** The SVG frame at `angle`, decimated until it fits the element's limit. */
export const svgFrame = (model: Model, angle: number) => {
  const key = `svg:${angle}`
  for (;;) {
    const faces = facesFor(model, model.svgBudget)
    const cached = model.frames.get(key)
    if (cached) return { svg: cached, shown: faces.count }
    const svg = toSvg(project(model.mesh, faces, angle), SVG_WIDTH, SVG_HEIGHT)
    if (svg.length <= SVG_LIMIT || model.svgBudget < 200) {
      return { svg: remember(model, key, svg), shown: faces.count }
    }
    // Every angle draws the same faces, so a smaller budget clears the frames drawn so far.
    model.svgBudget = Math.floor(model.svgBudget * 0.75)
    for (const name of [...model.frames.keys()]) if (name.startsWith('svg:')) model.frames.delete(name)
  }
}

/** The terminal frame at `angle`, as Raster cells. */
export const cellFrame = (model: Model, angle: number, columns: number, rows: number) => {
  const key = `cells:${angle}:${columns}x${rows}`
  const faces = facesFor(model, CELL_BUDGET)
  const cached = model.frames.get(key)
  if (cached) return { cells: cached, shown: faces.count }

  return { cells: remember(model, key, toCells(project(model.mesh, faces, angle), columns, rows)), shown: faces.count }
}

export const formatBytes = (bytes: number) => {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`

  return `${(bytes / 1024 / 1024).toFixed(1)} MB`
}

const plural = (n: number, word: string) => `${n.toLocaleString('en-US')} ${word}${n === 1 ? '' : 's'}`

/** The info strip: name, triangles, materials, size and bounding box. */
export const infoLine = (model: Model, shown: number) => {
  const { mesh } = model
  const dims = [0, 1, 2].map(c => (mesh.max[c]! - mesh.min[c]!).toFixed(2)).join(' x ')
  const triangles =
    shown < mesh.triangleCount
      ? `${plural(mesh.triangleCount, 'triangle')} (${shown.toLocaleString('en-US')} drawn)`
      : plural(mesh.triangleCount, 'triangle')

  return `${model.name}  ${triangles}  ${plural(mesh.palette.length, 'material')}  ${formatBytes(model.size)}  ${dims} m`
}

export const isTextured = (model: Model) => model.mesh.palette.some(material => material.isTextured)

const escapeHtml = (text: string) =>
  text.replace(/[&<>"']/g, ch => `&#${ch.charCodeAt(0)};`)

/**
 * The page "Open in browser" writes, split around the GLB's base64 so a
 * shell can stream the file between them: <model-viewer> orbits, zooms
 * and draws the textures.
 */
export const viewerPage = (name: string) => {
  const title = escapeHtml(name)

  return {
    head:
      `<!doctype html><html><head><meta charset="utf-8"><title>${title}</title>` +
      '<meta name="viewport" content="width=device-width, initial-scale=1">' +
      '<script type="module" src="https://unpkg.com/@google/model-viewer@4/dist/model-viewer.min.js"></script>' +
      '<style>html,body{margin:0;height:100%;background:#202124;color:#ddd;font:13px system-ui}' +
      'model-viewer{width:100%;height:100%}p{position:fixed;left:12px;bottom:4px;margin:0;opacity:.7}</style>' +
      `</head><body><model-viewer camera-controls auto-rotate shadow-intensity="1" alt="${title}" ` +
      'src="data:model/gltf-binary;base64,',
    tail: `"></model-viewer><p>${title} - drag to orbit, scroll to zoom</p></body></html>\n`,
  }
}

