// A small flat-shaded renderer: decimate by vertex clustering, turn and tilt,
// cull back faces, shade by normal, sort back to front, then draw the faces as
// SVG paths (desktop) or as half-block cells (terminal).

import type { Mesh } from './glb'

export type Faces = {
  positions: Float32Array
  materials: Uint16Array
  /** sRGB 0..255, three per face, when the mesh has sampled colors. */
  colors?: Uint8Array
  count: number
}

/** A face on screen: corners in -1..1 (y up), depth, sRGB color 0..255. */
type Projected = {
  x: [number, number, number]
  y: [number, number, number]
  z: number
  r: number
  g: number
  b: number
}

export const PITCH_DEGREES = 20
const LIGHT = (() => {
  const v = [-0.35, 0.55, 0.75]
  const n = Math.hypot(v[0]!, v[1]!, v[2]!)

  return v.map(c => c / n) as [number, number, number]
})()
const AMBIENT = 0.32
// Shade in steps, so neighbouring faces of one color share a path.
const SHADE_LEVELS = 24
// The model's bounding sphere spans this share of the frame's shorter side, at any turn.
const FILL = 0.47

/**
 * At most `budget` faces: the mesh itself when it fits, else a vertex
 * clustering on an ever coarser grid until it does.
 */
export const decimate = (mesh: Mesh, budget: number): Faces => {
  if (mesh.triangleCount <= budget) {
    return { positions: mesh.positions, materials: mesh.materials, colors: mesh.colors, count: mesh.triangleCount }
  }
  const size = Math.max(mesh.max[0] - mesh.min[0], mesh.max[1] - mesh.min[1], mesh.max[2] - mesh.min[2]) || 1
  // A closed surface clustered on a G-cell grid keeps about 4 G^2 faces; start a little finer.
  let grid = Math.max(2, Math.min(256, Math.round(Math.sqrt(budget / 4) * 1.4)))
  // Settle on the finest grid that fits: shrink while over budget, grow while well under it.
  let best: Faces | undefined
  const tried = new Set<number>()
  for (let attempt = 0; attempt < 12 && !tried.has(grid); attempt += 1) {
    tried.add(grid)
    const faces = cluster(mesh, grid, size)
    const fits = faces.count <= budget
    if (fits && (!best || faces.count > best.count)) best = faces
    if (fits && (faces.count >= budget * 0.7 || grid >= 256)) break
    if (!fits && grid <= 2) break
    const next = grid * Math.sqrt(budget / Math.max(1, faces.count)) * 0.95
    grid = Math.max(2, Math.min(256, fits ? Math.ceil(next) : Math.floor(next)))
  }
  if (best) return best

  // Coarser than a 2-cell grid cannot merge more; keep the first faces that fit.
  const coarsest = cluster(mesh, 2, size)
  const count = Math.min(coarsest.count, budget)

  return {
    positions: coarsest.positions.slice(0, count * 9),
    materials: coarsest.materials.slice(0, count),
    colors: coarsest.colors?.slice(0, count * 3),
    count,
  }
}

const cluster = (mesh: Mesh, grid: number, size: number): Faces => {
  const cellOf = new Map<number, number>()
  const sums: number[] = []
  const counts: number[] = []
  const vertexCells = new Uint32Array(mesh.triangleCount * 3)
  const p = mesh.positions
  const [minX, minY, minZ] = mesh.min
  const top = grid - 1
  const perUnit = grid / size
  for (let v = 0; v < mesh.triangleCount * 3; v += 1) {
    const cx = Math.min(top, Math.floor((p[v * 3]! - minX) * perUnit))
    const cy = Math.min(top, Math.floor((p[v * 3 + 1]! - minY) * perUnit))
    const cz = Math.min(top, Math.floor((p[v * 3 + 2]! - minZ) * perUnit))
    const key = (cx * grid + cy) * grid + cz
    let index = cellOf.get(key)
    if (index === undefined) {
      index = counts.length
      cellOf.set(key, index)
      counts.push(0)
      sums.push(0, 0, 0)
    }
    counts[index]! += 1
    sums[index * 3]! += p[v * 3]!
    sums[index * 3 + 1]! += p[v * 3 + 1]!
    sums[index * 3 + 2]! += p[v * 3 + 2]!
    vertexCells[v] = index
  }

  const seen = new Set<string>()
  const kept: number[] = []
  for (let t = 0; t < mesh.triangleCount; t += 1) {
    const a = vertexCells[t * 3]!
    const b = vertexCells[t * 3 + 1]!
    const c = vertexCells[t * 3 + 2]!
    if (a === b || b === c || a === c) continue
    const key = [a, b, c].sort((m, n) => m - n).join(',')
    if (seen.has(key)) continue
    seen.add(key)
    kept.push(t)
  }

  const positions = new Float32Array(kept.length * 9)
  const materials = new Uint16Array(kept.length)
  const colors = mesh.colors ? new Uint8Array(kept.length * 3) : undefined
  kept.forEach((t, i) => {
    colors?.set(mesh.colors!.subarray(t * 3, t * 3 + 3), i * 3)
    for (let k = 0; k < 3; k += 1) {
      const cell = vertexCells[t * 3 + k]!
      for (let axis = 0; axis < 3; axis += 1) {
        positions[i * 9 + k * 3 + axis] = sums[cell * 3 + axis]! / counts[cell]!
      }
    }
    materials[i] = mesh.materials[t]!
  })

  return { positions, materials, colors, count: kept.length }
}

/** The visible faces at a turn of `angle` degrees, farthest first, inside the unit circle. */
export const project = (mesh: Mesh, faces: Faces, angle: number): Projected[] => {
  const center = [0, 1, 2].map(c => (mesh.min[c]! + mesh.max[c]!) / 2)
  const size = Math.max(mesh.max[0] - mesh.min[0], mesh.max[1] - mesh.min[1], mesh.max[2] - mesh.min[2]) || 1
  const yaw = (angle * Math.PI) / 180
  const pitch = (PITCH_DEGREES * Math.PI) / 180
  const [cy, sy, cp, sp] = [Math.cos(yaw), Math.sin(yaw), Math.cos(pitch), Math.sin(pitch)]
  // The farthest corner from the centre: turning never moves the model past it.
  let radius = 0
  for (let o = 0; o < faces.count * 9; o += 3) {
    const d = Math.hypot(faces.positions[o]! - center[0]!, faces.positions[o + 1]! - center[1]!, faces.positions[o + 2]! - center[2]!)
    if (d > radius) radius = d
  }
  const unit = radius || size

  const out: Projected[] = []
  const vx = [0, 0, 0]
  const vy = [0, 0, 0]
  const vz = [0, 0, 0]
  for (let t = 0; t < faces.count; t += 1) {
    for (let k = 0; k < 3; k += 1) {
      const o = t * 9 + k * 3
      const x = (faces.positions[o]! - center[0]!) / unit
      const y = (faces.positions[o + 1]! - center[1]!) / unit
      const z = (faces.positions[o + 2]! - center[2]!) / unit
      const x1 = x * cy + z * sy
      const z1 = -x * sy + z * cy
      vx[k] = x1
      vy[k] = y * cp - z1 * sp
      vz[k] = y * sp + z1 * cp
    }
    const ax = vx[1]! - vx[0]!
    const ay = vy[1]! - vy[0]!
    const az = vz[1]! - vz[0]!
    const bx = vx[2]! - vx[0]!
    const by = vy[2]! - vy[0]!
    const bz = vz[2]! - vz[0]!
    let nx = ay * bz - az * by
    let ny = az * bx - ax * bz
    let nz = ax * by - ay * bx
    const length = Math.hypot(nx, ny, nz)
    if (length === 0) continue
    // Back faces go even on double-sided materials: a closed model hides them anyway,
    // and skipping them leaves the budget for the side that shows.
    if (nz <= 0) continue
    const lambert = Math.max(0, (nx * LIGHT[0] + ny * LIGHT[1] + nz * LIGHT[2]) / length)
    const shade = Math.round((AMBIENT + (1 - AMBIENT) * lambert) * SHADE_LEVELS) / SHADE_LEVELS
    let [r, g, b] = (mesh.palette[faces.materials[t]!]?.color ?? [0.8, 0.8, 0.8]).map(c => c * 255)
    if (faces.colors) [r, g, b] = [faces.colors[t * 3]!, faces.colors[t * 3 + 1]!, faces.colors[t * 3 + 2]!]
    out.push({
      x: [vx[0]!, vx[1]!, vx[2]!],
      y: [vy[0]!, vy[1]!, vy[2]!],
      z: (vz[0]! + vz[1]! + vz[2]!) / 3,
      r: Math.round(Math.min(255, r! * shade)),
      g: Math.round(Math.min(255, g! * shade)),
      b: Math.round(Math.min(255, b! * shade)),
    })
  }

  return out.sort((m, n) => m.z - n.z)
}

const hex = (r: number, g: number, b: number) =>
  `#${[r, g, b].map(c => c.toString(16).padStart(2, '0')).join('')}`

/**
 * The faces as one SVG document: consecutive faces of one color share a path.
 * `width` and `height` are the viewBox; the element scales it to its slot.
 */
export const toSvg = (faces: Projected[], width: number, height: number) => {
  const scale = Math.min(width, height) * FILL
  const parts: string[] = [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}">`,
    // A hairline of each face's own color closes the seams between faces.
    '<g stroke-width=".8" stroke-linejoin="round">',
  ]
  let fill = ''
  let d = ''
  const flush = () => {
    if (d) parts.push(`<path fill="${fill}" stroke="${fill}" d="${d}"/>`)
    d = ''
  }
  for (const face of faces) {
    const color = hex(face.r, face.g, face.b)
    if (color !== fill) {
      flush()
      fill = color
    }
    const point = (k: number) =>
      `${Math.round(width / 2 + face.x[k]! * scale)} ${Math.round(height / 2 - face.y[k]! * scale)}`
    d += `M${point(0)} ${point(1)} ${point(2)}z`
  }
  flush()
  parts.push('</g></svg>')

  return parts.join('')
}

const DEFAULT_COLOR = 0x01000000

/**
 * The faces drawn into `columns` x `rows` terminal cells, two pixels per cell
 * (the upper and lower half block), as RasterProps `cells`.
 */
export const toCells = (faces: Projected[], columns: number, rows: number) => {
  const width = columns
  const height = rows * 2
  const pixels = new Int32Array(width * height).fill(-1)
  const scale = Math.min(width, height) * FILL
  for (const face of faces) {
    const xs = face.x.map(x => width / 2 + x * scale)
    const ys = face.y.map(y => height / 2 - y * scale)
    const color = (face.r << 16) | (face.g << 8) | face.b
    const minX = Math.max(0, Math.floor(Math.min(...xs)))
    const maxX = Math.min(width - 1, Math.ceil(Math.max(...xs)))
    const minY = Math.max(0, Math.floor(Math.min(...ys)))
    const maxY = Math.min(height - 1, Math.ceil(Math.max(...ys)))
    const edge = (a: number, b: number, px: number, py: number) =>
      (xs[b]! - xs[a]!) * (py - ys[a]!) - (ys[b]! - ys[a]!) * (px - xs[a]!)
    const area = edge(0, 1, xs[2]!, ys[2]!)
    if (area === 0) continue
    for (let py = minY; py <= maxY; py += 1) {
      for (let px = minX; px <= maxX; px += 1) {
        const cx = px + 0.5
        const cy = py + 0.5
        const w0 = edge(1, 2, cx, cy) / area
        const w1 = edge(2, 0, cx, cy) / area
        const w2 = edge(0, 1, cx, cy) / area
        if (w0 >= 0 && w1 >= 0 && w2 >= 0) pixels[py * width + px] = color
      }
    }
  }

  const words = new Uint32Array(columns * rows * 3)
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const top = pixels[row * 2 * width + column]!
      const bottom = pixels[(row * 2 + 1) * width + column]!
      const o = (row * columns + column) * 3
      if (top < 0 && bottom < 0) {
        words.set([0x20, DEFAULT_COLOR, DEFAULT_COLOR], o)
      } else if (top < 0) {
        words.set([0x2584, bottom, DEFAULT_COLOR], o) // lower half block
      } else {
        words.set([0x2580, top, bottom < 0 ? DEFAULT_COLOR : bottom], o) // upper half block
      }
    }
  }

  return toBase64(littleEndian(words))
}

const littleEndian = (words: Uint32Array) => {
  const bytes = new Uint8Array(words.length * 4)
  const view = new DataView(bytes.buffer)
  words.forEach((word, i) => view.setUint32(i * 4, word, true))

  return bytes
}

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

export const toBase64 = (bytes: Uint8Array) => {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i]!
    const b = bytes[i + 1] ?? 0
    const c = bytes[i + 2] ?? 0
    out += ALPHABET[a >> 2]! + ALPHABET[((a & 3) << 4) | (b >> 4)]!
    out += i + 1 < bytes.length ? ALPHABET[((b & 15) << 2) | (c >> 6)]! : '='
    out += i + 2 < bytes.length ? ALPHABET[c & 63]! : '='
  }

  return out
}

const DECODE = new Map([...ALPHABET].map((ch, i) => [ch, i]))

export const fromBase64 = (text: string) => {
  const clean = text.replace(/[^A-Za-z0-9+/]/g, '')
  const bytes = new Uint8Array(Math.floor((clean.length * 3) / 4))
  let at = 0
  for (let i = 0; i < clean.length; i += 4) {
    const [a, b, c, d] = [0, 1, 2, 3].map(k => DECODE.get(clean[i + k] ?? 'A') ?? 0) as [number, number, number, number]
    const n = (a << 18) | (b << 12) | (c << 6) | d
    if (at < bytes.length) bytes[at++] = n >> 16
    if (at < bytes.length) bytes[at++] = (n >> 8) & 255
    if (at < bytes.length) bytes[at++] = n & 255
  }

  return bytes
}

