import type { ClientModule } from 'claude-code'

type DragProps = { label?: string }

/**
 * The surface that turns the model while dragged: each move posts the cells
 * the pointer travelled, and keys post turns and zooms; the hooks module
 * turns those into camera moves. With a `label` it is a strip of text; without
 * one it draws nothing, a transparent layer the terminal lays over the picture.
 */
const DragStrip: ClientModule<DragProps, { isReady: true }> = (props, surface) => {
  if (surface.state === undefined) {
    let last: { x: number; y: number } | undefined
    surface.onPointer(event => {
      const x = event.fine?.x ?? event.x
      const y = event.fine?.y ?? event.y
      if (event.type === 'down') {
        last = { x, y }
      } else if (event.type === 'move' && last && event.button !== undefined) {
        const dx = Math.trunc(x - last.x)
        const dy = Math.trunc(y - last.y)
        if (dx !== 0 || dy !== 0) {
          surface.post({ dx, dy })
          last = { x: last.x + dx, y: last.y + dy }
        }
      } else if (event.type === 'up') {
        last = undefined
      }
    })
    // Keys name the move, as the buttons do; a drag posts the pointer's travel.
    surface.onKey(event => {
      if (event.key === 'left') surface.post({ turn: -1 })
      else if (event.key === 'right') surface.post({ turn: 1 })
      else if (event.key === 'up') surface.post({ tilt: -1 })
      else if (event.key === 'down') surface.post({ tilt: 1 })
      else if (event.key === '+' || event.key === '=') surface.post({ zoom: 1 })
      else if (event.key === '-') surface.post({ zoom: -1 })
    })
    surface.setState({ isReady: true })
  }
  const { Box, Text } = surface.elements
  if (props.label === undefined) return <Box width={surface.columns || 1} height={surface.rows || 1} />

  return (
    <Box>
      <Text dimColor>{props.label}</Text>
    </Box>
  )
}

export default DragStrip

