export type ViewerMode = 'vector' | 'live'

export type ViewerView = {
  /** The GLB on screen, absolute; null before /meshy-view. */
  path: string | null
  /** Turn around the vertical axis, degrees. */
  angle: number
  /** Tilt, degrees from straight above: 90 is level (live mode). */
  phi: number
  /** Camera distance, percent of the fitted distance (live mode). */
  zoom: number
  isAutoRotating: boolean
  /** True while the viewer pane is open. */
  isOpen: boolean
  /** `live` draws real frames from headless Chrome in a kitty-graphics terminal; `vector` draws faces. */
  mode: ViewerMode
}

/** Shown above the prompt when the pane waits unplaced. */
export type ViewerHint = { path: string; reason: string }

declare module 'claude-code' {
  interface PluginState {
    'meshy-viewer': {
      view: ViewerView
      hint: ViewerHint | null
      /** meshy-tray task ids whose "View" offer was taken or dismissed. */
      dismissed: string[]
    }
  }
}
